  throw new Error('forced persistence failure');
};

await expect(
  processNextJob({ finalizeReady: failFinalization }),
).rejects.toThrow('forced persistence failure');

const interruptedJob = await prisma.processingJob.findUniqueOrThrow({
  where: { id: jobId },
  include: { sourceVersion: true },
});

