  const job = await prisma.processingJob.findUnique({
    where: { id: context.req.param('jobId') },
    select: { id: true, sourceVersionId: true, status: true, errorCode: true },
  });

  return job
    ? context.json({ data: job }, 200)
    : context.json({ error: { code: 'JOB_NOT_FOUND' } }, 404);
});

app.get('/sources/:sourceId/versions', async (context) => {
  const versions = await prisma.sourceVersion.findMany({
    where: { sourceId: context.req.param('sourceId') },
    select: {
      id: true,
      status: true,
      rawContent: true,
      normalizedContent: true,
      checksumSha256: true,
    },
  });

  return context.json({ data: versions }, 200);
