import { processNextJob } from './process-next-job.js';

try {
  const processed = await processNextJob();
  console.info(JSON.stringify({ event: 'worker_iteration', processed }));
} catch (error) {
  console.error(
    JSON.stringify({ event: 'worker_failed', error: error instanceof Error ? error.message : 'unknown' }),
  );
  process.exitCode = 1;
} finally {
  await prisma.$disconnect();
}
```

Dans Compose, un profil évite que ce worker **une itération** ne démarre avant la création du job. La commande explicite `docker compose run --rm worker` l’active au bon moment :

```yaml
